{
  "name": "Clause 41C Senior Circuit Breaker Tax Credit",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "tax_year_2025": {
        "single_not_head_of_household": 75000,
        "head_of_household": 94000,
        "married_filing_jointly": 112000
      },
      "notes": [
        "The program is a Massachusetts refundable property tax credit for a taxpayer age 65 or older.",
        "For married filing jointly, either the taxpayer or spouse must be 65 or older by the end of the tax year.",
        "The income limit is the taxpayer's 'total income' as defined for the credit."
      ]
    },
    "asset_limits": {
      "applies": false,
      "details": "No separate asset limit applies to the Massachusetts Senior Circuit Breaker Tax Credit."
    },
    "other_requirements": [
      "Must be a Massachusetts resident who owns or rents a principal residence in Massachusetts.",
      "Must occupy the property as a principal residence.",
      "Must file a Massachusetts state income tax return.",
      "Must include Schedule CB (Circuit Breaker Credit) with the return.",
      "For homeowners, the assessed valuation of the principal residence cannot exceed the annually set maximum amount for the tax year."
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Refundable Massachusetts income tax credit of up to $2,820 for tax year 2025.",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: File your Massachusetts state income tax return through MassTaxConnect and include Schedule CB",
      "Mail: Submit Form 1 or Form 1-NR/PY with Schedule CB by mail"
    ],
    "processing_time": "Processed with the Massachusetts income tax return; no separate standalone approval timeline is published.",
    "waitlist": null,
    "forms": [
      "Schedule CB (2025 Massachusetts Senior Circuit Breaker Credit)",
      "Massachusetts Form 1",
      "Massachusetts Form 1-NR/PY"
    ],
    "documents": [
      "Completed Massachusetts tax return",
      "Schedule CB",
      "Proof of age if needed to substantiate eligibility",
      "Income records needed to calculate total income",
      "Property tax records or rent records if applicable",
      "Home value/assessment information for homeowners"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available statewide to eligible Massachusetts residents; no county restriction.",
    "regional_variations": "The credit itself is statewide and uniform. Only local assistance or tax-prep support may vary by city or town.",
    "offices_or_providers": []
  },
  "official_source": "https://www.mass.gov/info-details/senior-circuit-breaker-tax-credit",
  "gotchas": [
    "This is not a separate welfare or service program; it is a refundable tax credit claimed on a Massachusetts tax return.",
    "You must file a Massachusetts return even if you normally do not file.",
    "The credit is only available if the taxpayer or spouse meets the age requirement by the end of the tax year.",
    "Homeowners also have an assessed-value cap in addition to the income cap.",
    "The credit amount changes by tax year, so families should use the current-year Schedule CB and instructions.",
    "Using the wrong filing status can disqualify a claim.",
    "Renters can qualify, not just homeowners."
  ],
  "data_shape_notes": "This program is a statewide refundable tax credit with annual inflation-adjusted income thresholds and annual maximum credit updates; it does not use waitlists, service tiers, or regional provider networks."
}
